import{_ as s,o as t,c as o,a0 as i}from"./chunks/framework.CShDTZbC.js";const S=JSON.parse('{"title":"解决 VitePress 构建过程中的Jekyll报出 SCSS 转换错误","description":"","frontmatter":{},"headers":[],"relativePath":"notes/dailynotes.md","filePath":"notes/dailynotes.md"}'),r={name:"notes/dailynotes.md"};function a(l,e,n,c,d,p){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="解决-vitepress-构建过程中的jekyll报出-scss-转换错误" tabindex="-1">解决 VitePress 构建过程中的Jekyll报出 SCSS 转换错误 <a class="header-anchor" href="#解决-vitepress-构建过程中的jekyll报出-scss-转换错误" aria-label="Permalink to &quot;解决 VitePress 构建过程中的Jekyll报出 SCSS 转换错误&quot;">​</a></h1><p><strong>摘要：</strong> 使用 GitHub Actions 自动部署 VitePress 时可能遇到的 SCSS 转换错误，并提供了一种简单的解决方案。</p><p>在使用 GitHub Actions 自动部署 VitePress 时，有时可能会遇到 SCSS 转换错误，错误信息类似于：</p><p><code>Conversion error: Jekyll::Converters::Scss encountered an error while converting &#39;assets/css/style.scss&#39;: No such file or directory @ dir_chdir - /github/workspace/docs</code></p><p><img src="https://s2.loli.net/2024/03/17/hikeJOSaXflpEqz.png" alt=""></p><p>这种错误会导致构建过程中失败，阻止网站的部署。</p><p>解决这个问题的方法其实很简单。我们需要到项目仓库的 Settings &gt; Pages &gt; Build and deployment 中进行设置。在默认情况下，VitePress 的源文件目录是 <code>/docs</code>，而我们需要将其改成 <code>/(root)</code>，即根目录。这样一来，GitHub Pages 将会从根目录开始构建网站，而不是从 <code>/docs</code> 目录。</p><h2 id="操作步骤" tabindex="-1">操作步骤： <a class="header-anchor" href="#操作步骤" aria-label="Permalink to &quot;操作步骤：&quot;">​</a></h2><ol><li>打开项目仓库的 Settings 页面。</li><li>在左侧导航栏中，选择 Pages 选项。</li><li>在 Build and deployment 部分，找到 Branch 选项。</li><li>将 Branch 的值从 <code>/docs</code> 改为 <code>/(root)</code>。</li><li>点击 Save 按钮保存更改。</li></ol><p><img src="https://s2.loli.net/2024/03/17/1vOm6V7J25hkxAj.png" alt=""></p><p>保存更改后，GitHub Pages 将会从根目录开始构建你的 VitePress 网站，这样就解决了 SCSS 转换错误的问题。</p><p>希望以上解决方案能够帮助你顺利部署你的 VitePress 网站！</p><h2 id="参考链接" tabindex="-1">参考链接 <a class="header-anchor" href="#参考链接" aria-label="Permalink to &quot;参考链接&quot;">​</a></h2><p><a href="https://github.com/orgs/community/discussions/76938" target="_blank" rel="noreferrer">https://github.com/orgs/community/discussions/76938</a></p>',14)])])}const u=s(r,[["render",a]]);export{S as __pageData,u as default};
